const items = $input.all();

function tryParseJson(text) {
  if (typeof text !== 'string') return null;
  const trimmed = text.trim();
  if (!trimmed) return null;

  try {
    return JSON.parse(trimmed);
  } catch (e) {}

  const firstBrace = trimmed.indexOf('{');
  const lastBrace = trimmed.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    const possibleJson = trimmed.slice(firstBrace, lastBrace + 1);
    try {
      return JSON.parse(possibleJson);
    } catch (e) {}
  }
  return null;
}

function extractResponseObject(item) {
  const j = item.json ?? {};

  if (typeof j.text === 'string' && j.text.trim()) {
    const parsed = tryParseJson(j.text);
    if (parsed) return parsed;
  }

  if (Array.isArray(j.output)) {
    for (const outputItem of j.output) {
      if (Array.isArray(outputItem.content)) {
        for (const contentItem of outputItem.content) {
          if (typeof contentItem.text === 'string' && contentItem.text.trim()) {
            const parsed = tryParseJson(contentItem.text);
            if (parsed) return parsed;
          }
        }
      }
      if (typeof outputItem.text === 'string' && outputItem.text.trim()) {
        const parsed = tryParseJson(outputItem.text);
        if (parsed) return parsed;
      }
    }
  }
  return j;
}

const output = [];
for (const item of items) {
  const parsed = extractResponseObject(item);
  output.push({ json: parsed });
}

return output;
